_url":"/docs/hiecm/v3/api/p2/endpoints/p2-link-abha-number-abha-otp/03-p2-post-v3-phr-app-login-profile-link#p1-process-link-request-via-abha-number","id":"hiecm.endpoint.p1-process-link-request-via-abha-number","summary":"Links the ABHA number to the signed in ABHA address after the OTP to the ABHA number's mobile is verified.","title":"Process Link Request via ABHA OTP","type":"endpoint"},{"doc_url":"/docs/hiecm/v3/api/p2/endpoints/p2-update-mobile/01-p2-post-v3-phr-app-login-profile-request-otp#p1-link-abha-number-via-aadhaar-request-otp","id":"hiecm.endpoint.p1-link-abha-number-via-aadhaar-request-otp","summary":"Starts linking an ABHA number to the signed in ABHA address with an Aadhaar OTP.","title":"Link ABHA number via AADHAAR-Request OTP","type":"endpoint"},{"doc_url":"/docs/hiecm/v3/api/m1/endpoints/m1-child-abha/02-m1-get-v3-enrollment-profile-children-child-abha#m1-enrolment-list-children","id":"hiecm.endpoint.m1-enrolment-list-children","summary":"Returns the child ABHA accounts held under a parent's ABHA.","title":"List the child ABHA accounts linked to this account","type":"endpoint"},{"doc_url":"/docs/hiecm/v3/registries/abha#abha-number-and-address","id":"hiecm.concept.abha-number-and-address","summary":"Two identifiers, the ABHA number for who the person is and the ABHA address for where their records are routed.","title":"ABHA number and ABHA address, and why there are two","type":"concept"}]}
